// Counterpart Scoring Model — Bootstrap Guide Section IX.B
// Fixed per Codex audit: uses structured prospect fields, not keyword scanning
// 7 factors, each scored 0-3, consistent naming throughout

const FACTORS = [
  'understanding',  // of unfair advantage
  'growth',         // joint growth potential
  'longterm',       // long-term orientation
  'breadth',        // organizational breadth
  'authority',      // decision authority
  'creativity',     // packaging creativity
  'risk_appetite'   // early engagement willingness
];

const CLASSIFICATIONS = [
  { min: 0.75, label: 'true_counterpart' },
  { min: 0.55, label: 'plausible_partner' },
  { min: 0.40, label: 'useful_channel' },
  { min: 0.25, label: 'prestige_target' },
  { min: 0.0, label: 'low_fit' }
];

// Known counterpart preset scores (from bootstrap guide Section IX.C)
const KNOWN_COUNTERPARTS = {
  'apco': { understanding: 3, growth: 3, longterm: 2, breadth: 3, authority: 2, creativity: 2, risk_appetite: 2, note: 'Best overall counterpart (AI governance + reputation + accountability)' },
  'fti': { understanding: 2, growth: 3, longterm: 2, breadth: 3, authority: 3, creativity: 2, risk_appetite: 2, note: 'Best evidence-native (investigations, defensibility, deepfake)' },
  'weber': { understanding: 2, growth: 2, longterm: 1, breadth: 2, authority: 2, creativity: 3, risk_appetite: 3, note: 'Best fast-experiment' },
  'fgs': { understanding: 1, growth: 2, longterm: 2, breadth: 3, authority: 3, creativity: 1, risk_appetite: 1, note: 'Best prestige whale' },
  'brunswick': { understanding: 2, growth: 2, longterm: 2, breadth: 2, authority: 2, creativity: 3, risk_appetite: 1, note: 'Best narrative complement' }
};

function classify(pct) {
  return (CLASSIFICATIONS.find(c => pct >= c.min) || { label: 'low_fit' }).label;
}

function scoreFromPreset(name, preset) {
  const scores = {};
  FACTORS.forEach(f => { scores[f] = preset[f] || 0; });
  const total = FACTORS.reduce((sum, f) => sum + scores[f], 0);
  const maxScore = FACTORS.length * 3;
  const pct = total / maxScore;
  return {
    prospect: name,
    scores,
    total,
    pct: Math.round(pct * 100),
    classification: classify(pct),
    source: 'preset',
    note: preset.note || ''
  };
}

function scoreFromIssue(issue) {
  const title = (issue.title || '').toLowerCase();
  const body = (issue.description || issue.body || '').toLowerCase();
  const text = title + ' ' + body;

  // Check known counterparts first
  for (const [key, preset] of Object.entries(KNOWN_COUNTERPARTS)) {
    if (text.includes(key)) {
      return scoreFromPreset(issue.title, preset);
    }
  }

  // Heuristic scoring using structured fields from the issue
  const scores = {};

  // Parse structured data if present in issue body
  const hasStructuredData = text.includes('company:') || text.includes('title:') || text.includes('lane:');

  // Understanding: does the prospect operate near artifact governance?
  scores.understanding = 
    text.includes('governance') || text.includes('compliance') || text.includes('audit') ? 2 :
    text.includes('security') || text.includes('risk') || text.includes('review') ? 1 : 0;

  // Growth: is their market expanding into AI?
  scores.growth =
    text.includes('ai practice') || text.includes('ai consulting') || text.includes('ai-assisted') ? 3 :
    text.includes('digital transformation') || text.includes('ai') ? 2 :
    text.includes('technology') || text.includes('innovation') ? 1 : 0;

  // Long-term: signals of strategic thinking
  scores.longterm =
    text.includes('strategic') || text.includes('partnership') || text.includes('long-term') ? 2 :
    text.includes('pilot') || text.includes('explore') ? 1 : 0;

  // Breadth: organizational size/reach  
  scores.breadth =
    text.includes('enterprise') || text.includes('global') || text.includes('fortune') ? 3 :
    text.includes('mid-market') || text.includes('series b') || text.includes('series c') ? 2 :
    text.includes('startup') || text.includes('seed') ? 1 : 0;

  // Authority: contact level
  scores.authority =
    text.includes('ceo') || text.includes('cto') || text.includes('ciso') || text.includes('vp') ? 3 :
    text.includes('director') || text.includes('head of') || text.includes('principal') ? 2 :
    text.includes('manager') || text.includes('lead') || text.includes('senior') ? 1 : 0;

  // Creativity: signals of novel approach
  scores.creativity =
    text.includes('innovative') || text.includes('new offering') || text.includes('creative') ? 2 :
    1; // Default 1 (unknown)

  // Risk appetite: willingness to engage early
  scores.risk_appetite =
    text.includes('early adopter') || text.includes('beta') || text.includes('experiment') ? 3 :
    text.includes('pilot') || text.includes('try') || text.includes('demo') ? 2 :
    text.includes('proven') || text.includes('established') ? 0 : 1;

  const total = FACTORS.reduce((sum, f) => sum + (scores[f] || 0), 0);
  const maxScore = FACTORS.length * 3;
  const pct = total / maxScore;

  return {
    prospect: issue.title,
    scores,
    total,
    pct: Math.round(pct * 100),
    classification: classify(pct),
    source: hasStructuredData ? 'structured' : 'heuristic',
    note: ''
  };
}

// Score all known counterparts first (always include these)
const presetResults = Object.entries(KNOWN_COUNTERPARTS).map(([name, preset]) => 
  scoreFromPreset(name.charAt(0).toUpperCase() + name.slice(1), preset)
);

// Score issues from Paperclip
const issues = $input.all().map(i => i.json);
const allIssues = Array.isArray(issues[0]) ? issues[0] : issues;
const issueResults = allIssues
  .filter(i => i.title)
  .slice(0, 30)
  .map(scoreFromIssue);

// Combine, deduplicate, sort
const allResults = [...presetResults, ...issueResults]
  .sort((a, b) => b.pct - a.pct);

const summary = {
  total_scored: allResults.length,
  true_counterparts: allResults.filter(r => r.classification === 'true_counterpart').length,
  plausible_partners: allResults.filter(r => r.classification === 'plausible_partner').length,
  useful_channels: allResults.filter(r => r.classification === 'useful_channel').length,
  prestige_targets: allResults.filter(r => r.classification === 'prestige_target').length,
  low_fit: allResults.filter(r => r.classification === 'low_fit').length,
  top_5: allResults.slice(0, 5).map(r => `${r.prospect} (${r.classification}, ${r.pct}%${r.note ? ' — ' + r.note : ''})`)
};

return [{ json: { summary, results: allResults.slice(0, 20) } }];

